-- D-22 ISSUE: FSQM-025 Food Defense Plan, FSQM-026 Food Fraud Vulnerability Assessment and Mitigation
-- Plan, FRM-014 Food Defense and Food Fraud Review and Test Record, REP-905 Visitor Log.
-- Approved GJM, effective 2026-10-29. First issue: revision "New".
--
-- Owner, 2026-10-29: issue now with the open items stated and dated (this reverses the 2026-10-08 decision to
-- wait for the production-room chime receiver). New facts: two bay doors besides the entrance; cameras cover
-- all indoor production and processing areas plus the parking lot and the outside, about 30 days kept; the
-- chemical locker is not bought (waits on funding). FSQM-025 no longer says chemicals are locked away.
-- Both plans gain a Part "Stated limitations at issue". Also: verification_schedule row
-- food_defense_fraud_review (yearly, FRM-014, first due 2027-01-31) and FSQM-017 v20 listing it.
-- Guarded on the md5 of each document as read from production on 2026-10-29.

begin;

do $guard$
declare h text;
begin
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-025' and status = 'draft';
  if h is distinct from 'f84274c6d270efeff80de2d9f7a26003' then raise exception 'FSQM-025 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-026' and status = 'draft';
  if h is distinct from 'b82043d2b6fcb69a224ae8c65ac88696' then raise exception 'FSQM-026 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FRM-014' and status = 'draft';
  if h is distinct from '13d4b77134a8afa371b4f0b04b54bb3b' then raise exception 'FRM-014 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'REP-905' and status = 'draft';
  if h is distinct from 'f1bc31ae0d1b2cb06778b69cd1fd9aa9' then raise exception 'REP-905 is not the document that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-017' and status = 'active' and revision = 'v19';
  if h is distinct from '7185ab9a71544277db17ab7a5e1048fa' then raise exception 'FSQM-017 is not the document that was read (md5 %).', h; end if;
  if exists (select 1 from public.verification_schedule where activity_key = 'food_defense_fraud_review') then
    raise exception 'a food_defense_fraud_review schedule row already exists.';
  end if;
end $guard$;

update public.sop_documents set content = $jx${"scope": "Both units, everything stored in them, and every person who enters: staff, visitors, contractors and collecting drivers. Fraud for money - a material that is not what it claims to be - is covered by FSQM-026.", "purpose": "This plan states how Adventure Bakery prevents somebody deliberately contaminating its product: the threats it has assessed, who may enter the site, how the open product is protected, and how the plan is tested each year.", "records": "• FRM-014 - one per yearly review and test, and one whenever the threat level is raised\n• FRM-905 visitor and contractor sign-in records, listed in REP-905\n• Staff timesheets\n• Training records for TRN-011 in the Team Portal", "procedure": ["The threat assessment", "• The SQF Practitioner assesses, with Senior Site Management, how somebody could deliberately contaminate product on this site, how likely it is, and what stops it (SQF 2.7.1.1). The result is below.", "• The site: two units in a light industrial complex, with warehousing and light industry as neighbours. A small team that knows each other. Every product is collected by the customer; the site runs no delivery vehicles. Product is vacuum sealed and boxed before it leaves.", "• Cameras cover every indoor production and processing area, the parking lot and the outside of the building. Recordings are kept for about 30 days before they are overwritten, so footage of an event is saved as soon as it is known about.", "• Who could do it, and how likely:", "◦ Somebody walking in during working hours - the main threat. The entrance is not locked while the team is working, and the team may all be in the production room. Control: a chime sounds whenever the entrance is opened - today in the office and reception, and in the production room once its receiver is fitted (see 'Stated limitations at issue') - and a member of the team goes to meet whoever has come in; the entrance opens into the reception area only; two closed doors and an \"employees only\" sign stand between reception and production; anyone the team does not know is stopped and taken back to the sign-in screen; cameras record.", "◦ A break-in when the site is empty - unlikely. Every outside door is locked whenever nobody is there, keys are held by named people only, and cameras record. There is no intruder alarm. A break-in is treated as possible tampering (see \"If tampering is suspected\").", "◦ A visitor or contractor - unlikely. Each one signs in, and is with a member of the team in the production and storage rooms.", "◦ A member of the team - unlikely. Control: access ends when the job does - keys come back and the Team Portal account is closed the day a person leaves.", "◦ A collecting driver - unlikely. Drivers do not enter the production or storage rooms; product is brought out to the vehicle.", "◦ Material tampered with before it arrives - unlikely. Control: the receipt check on FRM-301.", "• Threat level: LOW. It is raised, and this assessment is done again, when any of these happens: a break-in or an attempt at the site or in the complex; a threat made against the site, its staff or a customer's brand; tampering found or suspected; a person leaving on bad terms; a warning from the FDA, the police or a customer.", "Who is responsible", "• Senior Site Management is the senior site manager responsible for food defense. The name of the person is written on every FRM-014 review record (SQF 2.7.1.2 ii).", "• Every member of the team stops and asks anyone they do not know, and reports anything that looks tampered with. Nobody is asked to confront a person who seems dangerous: leave, and call the police.", "Who can get in", "• Keys and door codes are held only by the people named on the latest FRM-014. The last person out checks that every outside door is locked.", "• Visitors and contractors come in through the entrance to the reception area, where the sign-in screen is. A member of the team goes to reception when the entrance chime sounds. Nobody but the team goes past the \"employees only\" sign and the two doors to production unless a member of the team takes them. Both doors are kept closed. The only other outside doors are the two bay doors, one in each unit (415 and 425). They are for deliveries and collections, are opened only while goods are moving, and are closed and locked otherwise.", "• Only the team works in the production and storage rooms and on the equipment. A visitor or contractor is there only with a member of the team (FSQM-012 Part 6) (SQF 2.7.1.2 iii).", "The sensitive points", "• These are the places where product or an ingredient is open and one act could reach a whole batch (SQF 2.7.1.2 iv):", "◦ weighing and mixing - open ingredients and the mixer bowl;", "◦ the syrup - the kettle, and syrup kept for a later run;", "◦ baked product cooling on the racks, which can stand for hours and overnight;", "◦ dipping and packing, until the pouch is sealed.", "• Nobody but the team is at these points while product is open. Syrup that is kept is sealed and labelled. Product left to cool overnight is left in the locked building.", "• Before use, each container is looked at: an ingredient, a syrup container or a rack of product that is open, moved, or not as it was left is not used until Senior Site Management has seen it.", "Receiving and storing", "• A delivery is accepted only if it was expected, comes from an approved supplier (FRM-202) and its packs are sealed and undamaged; this is recorded on FRM-301. Deliveries are brought inside and are not left outside or unattended at the door (FSQM-035).", "• Cleaning chemicals are kept apart from food and packaging, as FSQM-032 requires, in the place it names. A lockable chemical locker is to be bought; until it is fitted the chemicals are not locked away (see 'Stated limitations at issue') (SQF 2.7.1.2 v).", "• Ingredients, packaging, labels, work in progress and finished product are all kept inside the locked building; nothing is stored outside. Printed packaging that is thrown away is defaced first (FSQM-037).", "• Transport: the collecting vehicle is checked and then secured by a lock or latch (FSQM-036, FRM-801). FSQM-036 named this assessment as the test of that rule. The assessment found no threat that the rule does not answer: the product is sealed, boxed and collected locally in small loads (SQF 2.7.1.2 vi).", "The record of who was on site", "• Staff: the timesheet shows who worked each day.", "• Visitors and contractors: each signs in and out on the entrance screen (FRM-905), which keeps the name, company, the person visited and the times. The Visitor Log (REP-905) lists every visit (SQF 2.7.1.2 vii).", "If tampering is suspected", "• Stop. Do not use, move or throw away what was found. Tell Senior Site Management at once.", "• Everything that could have been reached is put on hold on FRM-702 under FSQM-018. After a break-in that means every open or unsealed ingredient, all syrup, and all product not yet sealed.", "• Senior Site Management decides what is disposed of, calls the police, and tells the FDA and the customer where product may be affected (the contacts are on FRM-011). If product has already left the site, FSQM-023 starts. A CAPA is raised on FRM-007 (SQF 2.7.1.2 i).", "Instruction", "• All staff complete the food defense and food fraud training module (TRN-011) in the Team Portal when they start and each year after. The Team Portal keeps the record (SQF 2.7.1.3).", "Review and test", "• At least once a year, and whenever the threat level is raised, the SQF Practitioner and Senior Site Management review the assessment and this plan, and test it. Both are recorded on FRM-014 (SQF 2.7.1.4).", "• The test: a person the team does not know, arranged by Senior Site Management, arrives without warning and tries to walk from reception into the production room. It passes if the person is stopped and taken back to the sign-in screen before passing the second door. At the same visit: every outside door is locked and tried, the key holders are checked against the list, the entrance chime is heard in the production room with the equipment running, and the cameras are confirmed to be recording.", "• A failed test or a gap is raised as a CAPA on FRM-007, and the result goes to the management review.", "Stated limitations at issue", "> THIS PLAN WAS ISSUED ON 2026-10-29 WITH THESE OPEN, by management's decision. Each names what closes it, who owns it and when. When one closes, this Part and the line it affects are revised.", "• THE CHIME IN THE PRODUCTION ROOM. The entrance chime works today in the office and reception only, and the office is not always staffed. A receiver is fitted in the production room and tried with the mixer and the oven running by 2026-12-31. Until then, whoever works in production keeps both doors to reception closed and checks reception at each break. Owner: Senior Site Management.", "• THE CHEMICAL LOCKER. Bought and fitted by 2027-03-31; its purchase waits on funding, and the date is revised if that moves. Owner: Senior Site Management.", "• TRN-011 READ AGAINST THIS PLAN AND FSQM-026, and changed where it disagrees with them, by 2026-12-31. Owner: SQF Practitioner.", "• THE FIRST REVIEW AND TEST, recorded on FRM-014, by 2027-01-31 - after the production chime is fitted, so the test includes it. Owner: SQF Practitioner.", "Records", "• FRM-014 reviews and tests, FRM-905 visitor records, the timesheets, FRM-702 holds and FRM-007 CAPAs are kept as SOP-2.2.3 requires (SQF 2.7.1.4)."], "definitions": "Food defense: protecting food from deliberate contamination meant to cause harm.\nTampering: any sign that a material, product, container or piece of equipment has been deliberately interfered with.\nSensitive point: a place where product or an ingredient is open and one act could contaminate a whole batch.\nThreat level: how likely a deliberate act is judged to be. It is set in the threat assessment.", "responsibility": "Senior Site Management - the senior site manager responsible for food defense; holds the list of key holders, decides what is done when tampering is suspected, and arranges the yearly test.\nSQF Practitioner - carries out the threat assessment, keeps this plan current and records the review and test on FRM-014. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - stop and ask anyone they do not know, keep visitors with them, lock up, and report anything that looks tampered with.", "form_references": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-905 - Visitor Sign-In Log\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-011 - Customer, Recall and Crisis Contact List\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.1.1 to 2.7.1.4. The site had no food defense plan and no threat assessment.\n\nOWNER'S ANSWERS (2026-10-02): every outside door is locked when the site is empty and keys are held by named people; the entrance is NOT kept locked during working hours; reception is separated from production by two doors and an \"employees only\" sign; there are cameras and no intruder alarm; staff presence is shown by the timesheet.\n\nTHE NAME: SQF 2.7.1.2 ii asks for the name of the responsible senior manager. Controlled documents here name positions, so the plan names Senior Site Management and the person's name is written on each FRM-014 record.\n\nFSQM-036 named this assessment as the review of its lock-or-latch rule for collecting vehicles. The rule stands.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: add a yearly 'food defense and food fraud review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) the entrance chime working, and heard in the production room with the mixer and the oven running - the owner chose a chime (2026-10-02) over locking the entrance or an inner door, and the plan is written as if it is in place. On 2026-10-07 a chime is installed at the entrance and does not work; it is to be put right and tried before this plan is issued; (2) how many other outside doors there are; (3) what the cameras cover and how long recordings are kept; (4) that chemicals are locked away (the FSQM-032 locker); (5) the first review and test recorded on FRM-014.\n\nNew - 2026-10-29 - ISSUED, approved GJM, effective 2026-10-29, with the open items stated in a new Part 'Stated limitations at issue'. Management decided (owner, 2026-10-29) to issue before the production-room chime receiver is fitted, reversing the decision of 2026-10-08 to wait for it. OWNER'S ANSWERS (2026-10-29): besides the entrance there are two bay doors, one for each unit; the cameras cover all indoor production and processing areas, the parking lot and the outside of the building, with about 30 days of recordings; the chemical locker is not bought and waits on funding. Limitations: production chime by 2026-12-31; chemical locker by 2027-03-31; TRN-011 read against the plans by 2026-12-31; first FRM-014 review and test by 2027-01-31. The yearly review and test joined the verification schedule (FSQM-017 v20).", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.7.1.1, 2.7.1.2, 2.7.1.3, 2.7.1.4 (Food Defense Plan).\n\nFSQM-012 Good Manufacturing Practices Program - Part 6, visitors and contractors.\nFSQM-035 Receipt, Storage and Handling; FSQM-032 Chemical Control; FSQM-036 Loading, Transport and Unloading; FSQM-037 Waste Management.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-023 Product Withdrawal and Recall Program; FSQM-009 CAPA Program.\nFSQM-026 Food Fraud Vulnerability Assessment and Mitigation Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here."}$jx$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-025' and status = 'draft';

update public.sop_documents set content = $jx${"scope": "Every ingredient and packaging material bought or supplied to the site, and every finished product and label. Deliberate contamination meant to cause harm is covered by FSQM-025.", "purpose": "This plan states how Adventure Bakery finds where it could be the victim, or the source, of food fraud, and what it does to prevent it.", "records": "• FRM-014 - one per yearly review, and one when a material, supplier or claim is added\n• FRM-202 supplier approvals and FRM-207 material specifications\n• FRM-301 receipts\n• Training records for TRN-011 in the Team Portal", "procedure": ["How the vulnerability is assessed", "• The SQF Practitioner assesses every ingredient and packaging material, and the finished product, for food fraud: substitution, dilution, mislabeling and counterfeiting (SQF 2.7.2.1).", "• It is done once a year, and before a new material, a new supplier or a new label claim is approved (FRM-207, FRM-202, FRM-601).", "• Three questions are asked of each material:", "◦ History - is this kind of material a known target for fraud?", "◦ Gain - could somebody make money by diluting it, swapping it or copying it, and would it be hard to see?", "◦ Route - does the way it reaches the site vouch for it? A sealed, branded pack from a recognized distributor does. An online marketplace or an unbranded pack does not.", "• Rating: LOW - not a known target, and the route vouches for it. MEDIUM - a known target, or a route that does not vouch for it. HIGH - both. A MEDIUM or HIGH material has a control of its own below.", "• For each material the assessment also asks what the fraud could do to food safety - above all, an allergen that is not on the label.", "The materials", "• Rum - MEDIUM. Spirits are a known target: counterfeit and watered-down product, and illicit spirit can contain methanol. The rum is supplied by the customer whose brand is on the pack, in sealed bulk containers.", "• Flavorings and colors bought from an online marketplace - MEDIUM. Flavorings are a known target, and a marketplace is where relabelled and counterfeit goods are sold.", "• Pecans - MEDIUM. Nuts are a known target: cheaper nuts mixed in, and old crop sold as new. A different nut is an allergen that is not on the label. The pecans are supplied by the customer.", "• Soybean oil - LOW. Oils are a known target, but soybean oil is the cheapest common oil and there is nothing to gain by swapping it. It is bought as a sealed, branded pack.", "• Cake mix, sugar, liquid egg and pan release spray - LOW. Sealed, branded packs from recognized distributors; not known targets.", "• Packaging - film, pouches, boxes and labels - LOW. The fraud to guard against is somebody else using a customer's printed packaging; see \"The finished product\".", "The finished product", "• Mislabeling - the site packs under its customers' brands, so the label is the customer's statement and the site's act. What could be wrong: the ingredients or allergens, the statement \"contains less than 4% alcohol\", and the statement of who made the product and where.", "• Dilution or substitution - making the product with less rum, or with a cheaper material than the label declares.", "• Counterfeiting - another party selling product in a customer's packaging, or the site's product reaching anyone but the customer.", "The mitigation plan", "• Every material the site buys comes only from a supplier approved on FRM-202, and only as the named product of the named manufacturer on FRM-207. A material the customer supplies is entered on FRM-207 as well. A different brand is a new material: it is not used until it has been approved and its allergen statement checked (SOP-2.3.4, SOP-2.3.2).", "• Every delivery is checked on FRM-301: the brand and product match FRM-207, the pack is sealed, and it carries a lot code and a date. A pack that fails is not used; it is held on FRM-702.", "• Rum: supplied by the customer in bulk containers. A container is accepted only sealed and labelled, as the product the customer specifies, and is recorded on FRM-301 with its lot or bottling code. Rum that arrives unsealed or unlabelled is not used and the customer is told.", "• Online marketplace: used only for the materials and under the conditions written on that supplier's FRM-202 - sold by the marketplace itself or the brand's own store, the exact brand on FRM-207, seal and lot checked, the order number written on FRM-301. Where a distributor or the manufacturer can supply the material, it is bought there.", "• Pecans: supplied by the customer. A pack is accepted only sealed and labelled, declaring pecans only, and is recorded on FRM-301 with its lot code; the allergen statement on the pack is read at receipt. A pack that is unsealed, unlabelled or declares another nut is not used and the customer is told.", "• Signs that are acted on: a price well below the usual, a new seller, a pack or label that looks different, a broken seal, a missing lot code, a material that looks, smells or behaves differently. The material is held on FRM-702 and the SQF Practitioner decides.", "• The label: every label is approved on FRM-601 before use and checked against the approved label at release on FRM-701. A statement on a label - the alcohol content, who made the product and where - is approved only when the site holds the basis for it, or holds the customer's written confirmation that the statement is the customer's and that the customer holds the basis.", "• The recipe: ingredients are weighed to the recipe and recorded on FRM-520, so the product is made with what the label declares. A change of material or recipe goes through SOP-2.3.2 and a label check before it is used.", "• The packaging: customers' printed packaging is kept inside the locked building and defaced before it is thrown away (FSQM-037). Finished product is released only to the customer or the carrier it sends (FRM-801) (SQF 2.7.2.2).", "Instruction", "• All staff complete the food defense and food fraud training module (TRN-011) in the Team Portal. Whoever buys or receives materials is also shown this plan and the signs above (SQF 2.7.2.3).", "Review and verification", "• At least once a year the SQF Practitioner reviews this assessment and verifies that the plan is being followed, recorded on FRM-014 (SQF 2.7.2.4):", "◦ every material in use is on FRM-207 and is rated here;", "◦ every supplier used is approved on FRM-202;", "◦ recent FRM-301 receipts are checked against FRM-207 - brand, seal and lot;", "◦ recalls, supplier notices and fraud alerts for these materials are looked at;", "◦ the label statements are still true of the product.", "• Gaps and the corrective actions are written on FRM-014, and a CAPA is raised on FRM-007 where one is needed.", "Stated limitations at issue", "> THIS PLAN WAS ISSUED ON 2026-10-29 WITH THESE OPEN, by management's decision. Each names what closes it, who owns it and when. When one closes, this Part is revised.", "• RUM AND PECANS ON RECORD. Both are entered on FRM-207, and each delivery of either is recorded on FRM-301 with its lot or bottling code, by 2026-11-30. Owner: SQF Practitioner.", "• EVERY MATERIAL IN USE ON FRM-207 by 2026-12-31. Owner: SQF Practitioner.", "• THE ALCOHOL STATEMENT. The customer's written confirmation that \"contains less than 4% alcohol\" is its statement and that it holds the basis, by 2026-12-31. Owner: Senior Site Management.", "• WHO MADE THE PRODUCT. The box reads \"Manufactured by\" the brand owner at its own address, while the product is made at this site. The customer confirms in writing that the statement is correct for product made here, or changes it (for example to \"Manufactured for\" or \"Distributed by\"), by 2026-12-31. Owner: Senior Site Management.", "• THE FIRST REVIEW, recorded on FRM-014, by 2027-01-31. Owner: SQF Practitioner.", "Records", "• FRM-014 reviews, FRM-202, FRM-207, FRM-301, FRM-601 and FRM-007 are kept as SOP-2.2.3 requires (SQF 2.7.2.4)."], "definitions": "Food fraud: deceiving a buyer about food for money.\nSubstitution: a cheaper material in place of the one declared.\nDilution: a material made to go further with something cheaper.\nMislabeling: a label that says something untrue about the product.\nCounterfeiting: a copy sold as the real brand.\nVulnerability: how open a material or product is to fraud.", "responsibility": "SQF Practitioner - carries out the vulnerability assessment, keeps this plan current, decides what is done with a suspect material, and records the yearly review on FRM-014. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves suppliers, materials and labels, and reviews the FRM-014 record.\nWhoever buys - buys only approved materials from approved suppliers.\nWhoever receives - checks each delivery on FRM-301 and holds anything that looks wrong.", "form_references": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-202 - Supplier Approval & Evaluation Record\nFRM-207 - Material Specification Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-520 - Production Lot Record\nFRM-601 - label approval\nFRM-701 - Finished Product Release Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.2.1 to 2.7.2.4. The site had no food fraud vulnerability assessment and no mitigation plan.\n\nOWNER'S ANSWERS (2026-10-02): the rum is supplied by the customer; the label carries the statement \"contains less than 4% alcohol\". The materials were taken from the product's ingredient statement and the FRM-207 register. The pack declares pecans (\"Original with pecans\"), so pecans are assessed here.\n\nOWNER'S ANSWERS (2026-10-07): the rum arrives in sealed bulk containers; the pecans are supplied by the customer, not bought; the basis for the alcohol statement is held by the customer, and the site holds no calculation or laboratory result of its own.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: the yearly review is on the same verification schedule row as FSQM-025, against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) the rum containers carry a lot or bottling code, the rum is on FRM-207 and each delivery is on FRM-301; (2) the pecans are on FRM-207 and each delivery is on FRM-301; (3) the customer's written confirmation that \"contains less than 4% alcohol\" is its statement and that it holds the basis; (4) the box reads \"Manufactured by\" the brand owner at its own address, while this product is made at this site - the customer to confirm in writing that the statement is correct for product made here, or to correct it; (5) every material in use entered on FRM-207; (6) the first review recorded on FRM-014.\n\nNew - 2026-10-29 - ISSUED, approved GJM, effective 2026-10-29, with the open items listed before issue stated in a new Part 'Stated limitations at issue': rum and pecans on FRM-207 and FRM-301 by 2026-11-30; every material on FRM-207 by 2026-12-31; the customer's written confirmation of the alcohol statement and of the 'Manufactured by' statement by 2026-12-31; first review on FRM-014 by 2027-01-31. The yearly review is on the verification schedule with FSQM-025 (FSQM-017 v20).", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.7.2.1, 2.7.2.2, 2.7.2.3, 2.7.2.4 (Food Fraud).\n\nSOP-2.3.4 Vendor Approval; SOP-2.3.2 specification control.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-009 CAPA Program; FSQM-037 Waste Management.\nFSQM-025 Food Defense Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here."}$jx$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-026' and status = 'draft';

update public.sop_documents set content = $jx${"form_schema": {"sections": [{"id": "review", "title": "1. The review", "fields": [{"id": "how_this_works", "text": "One record for each yearly review and test of the Food Defense Plan (FSQM-025) and the Food Fraud plan (FSQM-026), done together. Also use it when the threat level is raised, after an incident, or when a material, supplier or label claim is added - then mark the lines you did not look at \"Not reviewed this time\".", "type": "info", "label": "How to use this"}, {"id": "reason", "type": "select", "label": "Reason", "width": "third", "options": ["Yearly review and test", "Threat level raised", "New material, supplier or claim", "After an incident"], "required": true, "showInList": true}, {"id": "date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "responsible_manager", "help": "The person's name (SQF 2.7.1.2 ii)", "type": "text", "label": "Senior manager responsible for food defense", "width": "third", "required": true}, {"id": "taking_part", "help": "Names and positions", "type": "textarea", "label": "Who took part", "required": true}]}, {"id": "defense", "title": "2. Food defense - review", "fields": [{"id": "defense_checks", "rows": {"mode": "fixed", "labels": ["The threats in FSQM-025 read through - they still match the site and its neighbours", "Since the last review: any break-in, threat, tampering or warning", "Every outside door locks, and was found locked when the site was empty", "Key and code holders match the list below; keys returned by anyone who left", "Visitors and contractors signed in and out - the Visitor Log (REP-905) looked at", "Timesheets kept for every working day", "Entrance chime working, and heard in the production room", "Cameras working and recording", "Chemicals locked away (FSQM-032)", "Deliveries checked on FRM-301 and not left outside", "Kept syrup and opened ingredients sealed and labelled", "Printed packaging kept inside; waste defaced (FSQM-037)", "TRN-011 completed by every member of staff"], "labelHeader": "Checked"}, "type": "grid", "label": "Food defense plan (FSQM-025)", "columns": [{"id": "result", "type": "select", "label": "Result", "width": 1, "options": ["In place - no gap", "Gap found", "Not applicable", "Not reviewed this time"], "required": true}, {"id": "notes", "type": "text", "label": "What was looked at, and what was found", "width": 3, "scanFact": "none"}], "rowDialog": true}, {"id": "key_holders", "help": "The name of every person who holds a key or a door code today", "type": "textarea", "label": "Key and code holders", "required": true}, {"id": "threat_level", "type": "select", "label": "Threat level", "width": "third", "options": ["Low - unchanged", "Raised"], "required": true, "showInList": true}, {"id": "threat_notes", "type": "textarea", "label": "If raised: why, and what has changed in the plan"}]}, {"id": "test", "title": "3. Food defense - test", "fields": [{"id": "test_result", "type": "select", "label": "Result", "width": "half", "options": ["Passed - stopped before the second door", "Failed - CAPA raised", "Not tested - this is not the yearly review"], "required": true}, {"id": "test_date", "type": "date", "label": "Date of the test", "width": "third"}, {"id": "test_scenario", "help": "Who came, which door, what time, who stopped them and where", "type": "textarea", "label": "What was tried, and what happened"}], "description": "The yearly test: a person the team does not know arrives without warning and tries to walk from reception into the production room."}, {"id": "fraud", "title": "4. Food fraud - review and verification", "fields": [{"id": "fraud_checks", "rows": {"mode": "fixed", "labels": ["Every material in use is on FRM-207 and is rated in FSQM-026", "Every supplier used since the last review is approved on FRM-202", "Recent FRM-301 receipts checked against FRM-207 - brand, seal and lot", "Rum received sealed and labelled, and recorded on FRM-301", "Online marketplace purchases - seller, seal and order number recorded on FRM-301", "Recalls, supplier notices and fraud alerts for our materials looked at", "Label statements still true of the product (FRM-601)", "Whoever buys and receives has been shown FSQM-026"], "labelHeader": "Checked"}, "type": "grid", "label": "Food fraud plan (FSQM-026)", "columns": [{"id": "result", "type": "select", "label": "Result", "width": 1, "options": ["In place - no gap", "Gap found", "Not applicable", "Not reviewed this time"], "required": true}, {"id": "notes", "type": "text", "label": "What was looked at, and what was found", "width": 3, "scanFact": "none"}], "rowDialog": true}, {"id": "changes", "help": "Write None if there were none. Each new one needs a rating in FSQM-026.", "type": "textarea", "label": "Materials, suppliers or label claims added or changed since the last review"}]}, {"id": "outcome", "title": "5. Gaps and actions", "fields": [{"id": "gaps", "help": "Write None if there were none", "type": "textarea", "label": "Gaps found, and the corrective action for each", "required": true}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "third"}]}, {"id": "sign", "title": "6. Sign-off", "fields": [{"id": "completed_by", "role": "filler", "type": "signature", "label": "Reviewed by", "required": true, "statement": "This is what was reviewed, tested and found."}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Senior Site Management", "required": true, "statement": "I have reviewed this record; the plans are verified, or the gaps above are being acted on."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{reason} - {date}"}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Issued with FSQM-025 and FSQM-026. Approved GJM, effective 2026-10-29."}$jx$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FRM-014' and status = 'draft';

update public.sop_documents set content = $jx${"attachments": [], "report_schema": {"legend": ["Every visitor and contractor signed in on the entrance screen (FRM-905), one line per visit. The record of who entered the site, for FSQM-025 (SQF 2.7.1.2 vii) and FSQM-012 Part 6.", "Signed out: No means the visitor never signed out on the screen. Entry: REFUSED means the visitor declared a symptom and was not let in; the visit is still recorded.", "GMP rules signed: the date of the FRM-906 acknowledgement the visit relied on. It is valid for twelve months."], "params": [{"id": "visited_between", "type": "date-range", "field": "visit_date", "label": "Visited between"}, {"id": "visitor", "op": "contains", "type": "text", "field": "visitor_name", "label": "Visitor"}, {"id": "purpose", "type": "select", "label": "Purpose", "column": "purpose"}, {"id": "signed_out", "type": "select", "label": "Signed out", "column": "signed_out"}, {"id": "entry", "type": "select", "label": "Entry", "column": "entry"}], "columns": [{"id": "date", "header": "Date", "source": {"kind": "field", "field": "visit_date"}}, {"id": "visitor", "header": "Visitor", "source": {"kind": "field", "field": "visitor_name"}}, {"id": "company", "header": "Company", "source": {"kind": "field", "field": "company"}}, {"id": "purpose", "header": "Purpose", "source": {"kind": "field", "field": "purpose"}}, {"id": "host", "header": "Here to see", "source": {"kind": "field", "field": "host"}}, {"id": "time_in", "header": "In", "source": {"kind": "field", "field": "time_in"}}, {"id": "time_out", "header": "Out", "source": {"kind": "field", "field": "time_out"}}, {"id": "signed_out", "header": "Signed out", "source": {"kind": "cases", "cases": [{"op": "notEmpty", "then": "Yes", "field": "time_out"}], "default": "No"}}, {"id": "entry", "header": "Entry", "source": {"map": {"Both": "Briefed and escorted", "Entry refused": "REFUSED", "Briefed — FRM-906 completed and signed": "Briefed", "Escorted at all times by an authorized employee": "Escorted"}, "kind": "map", "field": "entry_route", "fallback": ""}}, {"id": "ack_date", "header": "GMP rules signed", "source": {"kind": "field", "field": "ack_date"}}], "version": 1, "sourceStatus": "submitted", "sourceSopNumber": "FRM-905", "defaultDateField": "visit_date"}, "revision_history": "New - 2026-10-29 - Issued with FSQM-025. Approved GJM, effective 2026-10-29."}$jx$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'REP-905' and status = 'draft';

update public.sop_documents set content = $jx${"scope": "Every element of the SQF System operated at this site, and every activity by which the effectiveness of those elements is established or confirmed.\n\nIt does not restate the controls it schedules, and it does not duplicate their records. Good Manufacturing Practices are FSQM-012 and FSQM-022; sanitation is FRM-901, FRM-902 and FRM-903 with the machine SSOPs beneath them; temperature monitoring is SOP-401 and FRM-401; retention sampling is FSQM-014; product release is FSQM-020; dispatch is FSQM-036; corrective action is FSQM-009. This program supplies the method, the responsibility, the criteria and the schedule.", "purpose": "To state the methods, responsibility and criteria by which the site validates that its food safety controls achieve the results required of them, and verifies that those controls are being operated; and to hold the master verification schedule listing every verification activity, its frequency, the position responsible for it and the record that evidences it. It satisfies the Validation and Effectiveness and Verification Activities elements of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.5.1 and 2.5.2), both of which are Mandatory.", "records": "This program creates no record of its own. The record of each verification activity is the form named against it in Part 6, held and retained by the program that defines that form.\nThe schedule itself is a record, and it is Part 6 of this document. It is amended by revising this document.\nThe annual review of this program is evidenced by its revision, as it is for every program in this document set.\nRetention of the activity records: as set by each owning program; none is shorter than two years, or the shelf life of the product plus twelve months, whichever is longer, on the basis FSQM-009 Part 10 states.", "procedure": ["This program states how the site validates that its food safety controls achieve what they are meant to achieve, and how it verifies that those controls are being operated. It holds the master verification schedule required by 2.5.2.2, which is set out in Part 6.", "> Validation and verification are different questions and this program keeps them apart. Validation asks whether a control WOULD work: is the method capable of the result claimed for it. Verification asks whether it DID: was it carried out, by whom, and does the record show it. Monitoring is neither - it is the doing itself, and it lives in the programs below rather than here.", "This program schedules and verifies the controls that other programs define. It does not restate them, and it does not create a record of its own where one already exists.", "• Good Manufacturing Practices are defined by FSQM-012 and monitored under FSQM-022, whose monthly full-site inspection is recorded on FRM-913.", "• Sanitation is scheduled by FRM-901, confirmed daily on FRM-903 and verified on FRM-902, with the machine SSOP logs FRM-909 to FRM-912 beneath them.", "• Temperature monitoring is SOP-401, and its monthly review on FRM-401 is already written as the verification that the automatic monitoring worked.", "• Retention sampling is FSQM-014 and FRM-703; product release is FSQM-020 and FRM-701; dispatch is FSQM-036 and FRM-801; glass and brittle plastic is FRM-907.", "• Corrective and preventive action is FSQM-009, recorded on FRM-007.", "> Naming them rather than absorbing them is the point. An umbrella program that restates the controls beneath it creates two versions of every rule, and the day they disagree is the day the document set stops being evidence of anything. What this program adds is the method, the responsibility, the criteria and the schedule.", "> The same reasoning governs the records. Every activity on the schedule in Part 6 is recorded on the form named against it, and this program issues no general-purpose verification form of its own. A catch-all record beside a purpose-built one produces two accounts of a single activity, and is weaker evidence than either.", "Good Manufacturing Practices shall be confirmed to achieve the results required of them, and the confirmation shall be recorded.", "• The monthly site inspection on FRM-913 examines each Module 11 subsection against the Code and records what was found, not merely that a look was taken.", "• Sanitation verification on FRM-902 confirms that cleaning achieved its result rather than that cleaning was performed, which is what FRM-903 already confirms.", "• Where an inspection or a verification finds a practice that is not achieving its result, the finding is raised under FSQM-009 and the practice is changed. A finding closed without a change is a finding that was not believed.", "> WHAT THIS SITE CANNOT CURRENTLY DO, stated plainly rather than implied. Confirming a hygiene practice by measurement - environmental swabbing, ATP, indicator organisms - requires analysis, and this site performs none: FSQM-014 records that there is no on-site laboratory, no external laboratory and no reliance on supplier certificates of analysis. Confirmation here therefore rests on inspection and on record review.", "> That is a real limit and it is not closed by wording it carefully. The deliverable that changes it is the environmental monitoring program for ready-to-eat product, which introduces sampling, pathogen and indicator selection, and trending. When it is issued, this Part is revised to cite it and the analytical limb of 2.5.1.1 i is met properly. Until then this program does not claim more than inspection can support.", "Critical food safety limits shall be reviewed at least annually, and re-validated or justified against a regulatory standard whenever they change or whenever the process they control changes.", "• A limit that is re-validated shall record the evidence relied on. A limit justified by reference to a regulatory standard shall record the standard.", "• Where a limit changes, the change shall be assessed under Part 4 before it takes effect.", "> WRITTEN CONDITIONALLY, AND ON PURPOSE. The limits this Part governs are those established by the food safety plan, FSQM-016 Food Safety Plan (HACCP) - Rum Cake, issued 2026-10-29 as a limited plan. It replaces the unnumbered HACCP plan of 23 June 2026, which is archived, and identifies two critical control points:", "• CCP 1 — Baking. Hazard: survival of Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder. Critical limits: oven at least 350°F for at least 27 minutes. The June 2026 plan also set an internal product temperature of at least 180°F at the end of the bake; the product is not probed today. Monitoring: every oven load.", "• CCP 2 — Vacuum sealing in pouches. Hazard: loss of package integrity, which admits microbial contamination and ends shelf stability. Critical limits: vacuum level to the equipment specification; no visible leak, channel, wrinkle across the seal, or partial seal, and no air in the pouch; and seal width to the equipment specification. Monitoring: a visual check of every pouch as it comes off the sealer, for seal defects and for air in the pouch. At boxing, once the seal is cool, every pouch is looked at again for lost vacuum and one pouch from each lot is pull tested. A pull test is not done on a warm seal.", "> Both points are monitored and recorded by the production operator: CCP 1 on FRM-507 CCP 1 Baking Monitoring Record, and CCP 2 on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The internal product temperature at CCP 1 is not monitored, and FRM-507 records that each production day rather than leaving the column blank. The limits are now established by a controlled document, but they are not yet validated: FSQM-016 Part 9 states, with dates, the validation of the bake (including the internal temperature) and the vacuum level and seal width for this site's sealer, which are not yet confirmed.", "> The annual review and re-validation of critical limits is therefore carried on the schedule as not yet implemented rather than as a review somebody is failing to do: until the limits are validated there is nothing to re-validate. It is activated when the bake is validated and the CCP 2 specification is confirmed (FSQM-016 Part 9). The cooling steps after the bake are not critical control points (FSQM-016 Parts 7 and 8).", "> Two limits are in force today and are governed by the programs that state them, because they are real whether or not a HACCP plan names them: the refrigerator and freezer limits in SOP-401, reviewed monthly on FRM-401, and the sanitizer concentration stated in FRM-903 and the SSOPs. NEITHER IS A CRITICAL CONTROL POINT. Recording them as though they were would be the opposite error to ignoring them, and would put a CCP in the document set that no hazard analysis ever identified.", "A change to a process or a procedure shall be assessed for its effect on food safety controls BEFORE it takes effect, and the assessment shall be recorded.", "• The triggers are: a new or reformulated product; a change of process step, equipment, ingredient, supplier, packaging or label; a change to the layout of the site; and a change to who performs a monitoring or verification role.", "• The assessment records what control the change touches, whether that control remains effective, and what was altered to keep it so.", "• Where a dedicated record governs the change it is used: label changes are FRM-601 and REP-603, a new supplier is FRM-202, a new material is FRM-207, and a change arising out of a corrective action is recorded on its FRM-007.", "> Every other change that can alter whether the product is safe - a new product or recipe, a changed process step or limit, new or modified equipment that touches the product - is assessed and approved on FRM-015 under FSQM-007 Change Management Program. That program also states which changes need no record beyond the revision of the document that describes them, and how a change of people is handled.", "> The order matters more than the paperwork. A control assessed after the change it exists to control has already failed to control it - the same reasoning FSQM-036 Part 3 applies to introducing temperature-controlled transport, and FSQM-014 Part 2 to introducing analysis.", "The monitoring of Good Manufacturing Practices, of critical control points and of other food safety controls shall be verified, and the person responsible for verifying shall authorize each verified record.", "• Verification confirms that monitoring was carried out as required, that its results were within limits, and that anything outside limits was acted on.", "• The verification signature on the record IS the authorization required by 2.5.2.1. FRM-903, FRM-913, FRM-902, FRM-401, FRM-701, FRM-507 and FRM-606 each carry one, and it is not repeated anywhere else.", "• A person shall not verify their own monitoring where a second qualified person is available. Where one is not, the record shall say so.", "> That last rule is written the way FSQM-004 had to be rewritten. An absolute separation requirement made a legitimate single-operator run non-compliant, and 11.2.5.7 asks for QUALIFIED personnel rather than independent ones. A rule the site cannot always follow is worse than a weaker one it can: the first thing that happens to it is that it is ignored.", "> A verification that leaves no signature is indistinguishable from one that did not happen. That is why 2.5.2.1 names authorization separately from verification, and why the schedule names a position against every activity rather than leaving it to whoever is free.", "> CRITICAL CONTROL POINTS ARE VERIFIED ON THEIR OWN RECORDS. The production operator records the monitoring of the two critical control points in the site's HACCP plan on FRM-507 for baking and FRM-606 for vacuum sealing. Each entry carries a required verification signature and is not submitted until the reviewer has checked it against the critical limits and confirmed that every deviation has a recorded action; that signature is the authorization 2.5.2.1 requires. The review is scheduled weekly in Part 6, one activity per record. What it cannot yet confirm is stated on the forms: the internal product temperature at CCP 1, which is not monitored, and the CCP 2 vacuum level and seal width against a specification not yet confirmed for this site's machine.", "The master verification schedule is set out below. It states every verification activity, the frequency at which it is completed, the position responsible for it, and the record that evidences it.", "• Site GMP and food safety inspection — Monthly — SQF Practitioner — FRM-913", "• Review of daily sanitation and pre-operational records — Weekly — Production Supervisor — FRM-903", "• Sanitation verification — Weekly — SQF Practitioner — FRM-902", "• Temperature monitoring record review — Monthly — SQF Practitioner — FRM-401", "• Retention sample review and disposal — When a sample on the shelf passes its discard date — SQF Practitioner — that sample's own entry on FRM-703", "• Finished product release record review — Weekly — SQF Practitioner — FRM-701", "• Dispatch and vehicle loading record review — Weekly — SQF Practitioner — FRM-801", "• CCP 1 baking monitoring record review — Weekly — SQF Practitioner — FRM-507", "• CCP 2 vacuum sealing monitoring record review — Weekly — SQF Practitioner — FRM-606", "• Glass and brittle plastic register check — Monthly — Production Supervisor — FRM-907", "• Review of open and overdue corrective actions — Monthly — SQF Practitioner — FRM-009, under \"Open corrective actions\"; each CAPA itself is recorded on FRM-007 and listed on REP-007", "• Customer complaint review and trending — Monthly — SQF Practitioner — FRM-009, under \"Complaints, incidents and recalls\"; the complaints themselves are reported on FRM-002 and listed on REP-003", "• Monthly SQF update to senior site management — Monthly — SQF Practitioner — FRM-009; the update required by 2.1.2.2 and management's response to it, distinct from the annual management review above", "• Management review of the SQF System — Annually — Senior Site Management — FRM-001", "• Blackout period declaration to the certification body — Annually — Senior Site Management — FRM-006; dated from the period the declaration in force covers, not from when it was filed, and raised 90 days ahead of the next period", "• Annual review and re-validation of critical food safety limits — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting validation of the critical limits (FSQM-016 Part 9)", "• Annual review of the Validation and Verification Program — Annually — SQF Practitioner — evidenced by the revision of FSQM-017", "• Calibration of measuring and monitoring equipment — Monthly — SQF Practitioner — FRM-705", "• Preventive maintenance check of equipment and building — Monthly — SQF Practitioner — FRM-508", "• Backflow prevention device testing — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Potable water microbiological and chemical analysis — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Internal audit of the SQF System — Quarterly — SQF Practitioner — FRM-010", "• Traceability and mock recall test — Annually — SQF Practitioner — FRM-012", "• Crisis management plan review and test — Annually, before 1 June — Senior Site Management — FRM-013", "• Environmental monitoring sampling round — Every four months — SQF Practitioner — FRM-706", "• Food defense and food fraud review and test — Annually — SQF Practitioner — FRM-014", "> The schedule is maintained in the Team Portal under Compliance, where it is the same record the reminder system reads. Adding, retiring or re-timing an activity is done there, and the list above is this program's copy of it as at the effective date of this revision. A change to the schedule is therefore a revision of this program, and the annual review in Part 10 is the occasion that catches it.", "> AN ACTIVITY MARKED NOT YET IMPLEMENTED IS SCHEDULED AND IS NOT BEING PERFORMED, because the program that governs it has not been issued. Each names the deliverable that will bring it into force, no reminder is raised for it, and no record is expected against it.", "> Listing activities the site is not yet performing is deliberate and is the harder of the two options. Omitting them would produce a schedule that looked complete and was not, and an auditor comparing it against the Code would find the gaps anyway - having also learned that the schedule does not show them. Stating them is the position that survives being read carefully.", "Verification activities that have fallen due shall be raised to the whole team within the Team Portal, labelled with the position responsible for each.", "• The prompt is raised twice each working day from the schedule. Nothing is routed to an individual: the schedule names the responsible position, and the notification carries that label.", "• A prompt is cleared for the whole team by whoever acts on it, and the clearing records who and when.", "> A NOTIFICATION IS A PROMPT, NOT A RECORD. Clearing one does not perform the activity and is not evidence that it was performed. The record is the entry on the form the notification links to. The name and time against a cleared prompt show only that somebody took the prompt, and this program does not treat them as verification.", "> The distinction is worth defending because the failure it prevents is quiet. A feed that feels like a checklist becomes one that gets ticked, and a system whose evidence is a list of dismissals has replaced the work with the reminder about the work.", "Where a verification activity finds that a control is not effective, or was not carried out, the finding shall be raised under FSQM-009 and its corrective action recorded on FRM-007.", "• The activity that found it is still recorded as completed. A verification that finds a problem has succeeded, not failed.", "> Recording the failure and the verification separately keeps both true. Marking a verification incomplete because it found something would mean the schedule showed the activity as outstanding, which would raise it again the next morning and lose the finding in the noise.", "Records of verification activities are the records named against each activity in Part 6, held and retained by the programs that define them. This program creates no record of its own.", "The SQF Practitioner shall review this program at least annually, and whenever a program it schedules is issued, amended or withdrawn. The review is evidenced by the revision of this document.", "> That is how every program in this document set evidences its annual review, and it is why this one does not carry a review form. The schedule is the part that goes stale, and it goes stale quietly: an activity keeps its place on the list long after the program that governed it changed. The annual review is also the occasion on which the not yet implemented activities are re-examined, because each becomes real the day its deliverable is issued and nothing else will announce that to this document."], "definitions": "Validation: establishing that a control is capable of achieving the result claimed for it. It asks whether the control WOULD work.\n\nVerification: confirming that a control was operated as required and that its records show it. It asks whether the control DID work.\n\nMonitoring: carrying out the control and recording the result at the time. Monitoring is neither validation nor verification, and it lives in the program that defines the control.\n\nVerification activity: one scheduled task in Part 6, with a frequency, a responsible position and a named record.\n\nNot yet implemented: the status of a scheduled activity whose governing program has not been issued. The activity is listed and is not being performed.", "responsibility": "SQF Practitioner — owns this program and the schedule. Performs or assigns each verification activity, authorizes verified records, and raises findings under FSQM-009.\nProduction Supervisor — performs the verification activities assigned to that position, and ensures monitoring is carried out so that there is something to verify.\nProduction staff — carry out the monitoring that these activities verify, and complete the records that are its evidence.\nAdmin — maintains the records and their retention.\nSenior Site Management — provides the resources the schedule requires, reviews the system under 2.1.2, and is the authority for any decision to change an activity's frequency.", "form_references": "FRM-913 GMP / Food Safety Inspection Record; FRM-903 Daily Sanitation, Pre-Operation & Release Record; FRM-902 Sanitation Verification Log; FRM-901 Master Sanitation Schedule; FRM-401 Temperature Monitoring Review; FRM-703 Retention Sample Log; FRM-701 Finished Product Release Record; FRM-801 Dispatch and Vehicle Loading Record; FRM-907 Glass & Brittle Plastic Register; FRM-007 Corrective & Preventive Action Report; FRM-002 Customer Complaint Report; FRM-001 Management Review Record; FRM-507 CCP 1 Baking Monitoring Record; FRM-606 CCP 2 Vacuum Sealing Monitoring Record; FRM-705 Calibration Directory and Check Record; FRM-508 Monthly Maintenance Check; FRM-010 Internal Audit Record; FRM-015 Change Assessment Record", "revision_history": "v17 - 2026-10-16 - The retention sample reminder is raised when a sample is due.\n\nPart 6 listed the retention sample review and disposal as weekly, evidenced by FRM-703. One FRM-703 is one sample and is submitted only when that sample leaves the shelf, so while every sample was within its period the weekly reminder could never be discharged, and the only way to clear it was to record a sample as gone that was still on the shelf. FSQM-014 asks for no weekly review: a sample is kept until thirty days after the date on its pack and its disposal is recorded on FRM-703 when it leaves. The activity is now raised when a sample on the shelf passes its discard date, links to that sample, and is discharged by recording its disposal (owner's decision, 2026-10-16). The position responsible is unchanged.\n\nv16 - 2026-10-16 - The monthly CAPA review is evidenced by the monthly SQF update.\n\nPart 6 listed the review of open and overdue corrective actions against FRM-007. FRM-007 is the report of one corrective action, so it cannot show that the month's corrective actions were reviewed, and the schedule's reminder could never be discharged - the same fault v15 corrected for the complaint review. The review is done at the monthly SQF update and recorded on FRM-009 under \"Open corrective actions\", against the CAPA log REP-007; FSQM-009 v2 says so, and the schedule line and the reminder now do too (owner's decision, 2026-10-16). Frequency and the position responsible are unchanged.\n\nv15 - 2026-10-12 - The monthly complaint review is evidenced by the monthly SQF update.\n\nPart 6 listed the customer complaint review and trending against FRM-002. FRM-002 is the report of one complaint, so it cannot show that a month's complaints were reviewed, and the schedule's reminder could never be discharged. The review is done at the monthly SQF update and recorded on FRM-009 under \"Complaints, incidents and recalls\", against the log REP-003; the schedule line and the reminder now say so (owner's decision, 2026-10-12). Frequency and the position responsible are unchanged.\n\nRev New — written 2026-09-10 against SQF Food Safety Code: Food Manufacturing, Edition 9, 2.5.1 Validation and Effectiveness and 2.5.2 Verification Activities. ISSUED 2026-09-10, approved GJM (Senior Site Management), effective 2026-09-10.\n\nWHY IT EXISTS. The gap assessment scored 2.5.1.1, 2.5.2.1 and 2.5.2.2 and no controlled document covered validation or verification as a subject. Individual programs verified themselves - FSQM-022's monthly inspection, FRM-401's monthly review - but nothing held the schedule 2.5.2.2 requires or stated the method 2.5.1.1 and 2.5.2.1 require. Both clauses are Mandatory.\n\nIT SCHEDULES RATHER THAN RESTATES. Part 1 names every program whose controls this one verifies and defers to each. An umbrella that restates the controls beneath it creates two versions of every rule, and the day they disagree the document set stops being evidence. FSQM-036 Part 7 took the same approach to unloading, pointing back at FRM-301 rather than building a second receiving form.\n\nAMENDED 2026-09-10, BEFORE ISSUE — FRM-008 WAS REDUNDANT AND HAS BEEN DELETED. This program was first drafted with a companion form: FRM-008, carrying the printed schedule and a general-purpose verification activity record. The owner questioned whether that record was doing any work, and it was not. Eleven of the thirteen active activities already record on their own form. The two that did not dissolved on inspection: no active FSQM programme in this document set records its annual review on a form - the revision is the evidence, in all eight of them - and the annual re-validation of critical food safety limits belongs with the food safety plan that establishes those limits, which does not exist, so that activity is now carried as not yet implemented alongside CCP record review for the same reason.\n\nWith the record section serving nothing, what remained was a form with a printed table and nowhere to write. 2.5.2.2 asks the PROGRAMME to have a verification schedule, so the schedule became Part 6 of this document and FRM-008 was deleted. One document instead of two, and no second copy of the schedule to keep in step. FRM-008 returns to being an unused number.\n\nThe general-purpose record was also the wrong shape on its own terms. A catch-all beside a purpose-built record produces two accounts of one activity, and invites being filled in alongside the real form rather than instead of it. Part 1 now says so in terms.\n\nTHE ANNUAL REVIEW OF THIS PROGRAM is evidenced by its revision, which is both how every other programme here does it and something the application already records in sop_document_history. The schedule reads that history to know when the review last happened, so the activity is still prompted without a form existing to carry it.\n\n\n\nSETTLED AT ISSUE — 2026-09-10:\n\n1. WHO APPROVES. Senior Site Management, GJM. This program appoints verification responsibilities across every position including the SQF Practitioner's own, so approval by the role it assigns work to would have been the appointee approving their own appointment - the same reasoning FSQM-004 records.\n\n2. THE FREQUENCIES IN PART 6 ARE THE SITE'S, FROM THIS DATE. They were seeded as proposals to give the schedule a working shape and were issued without a separate confirmation pass, which is recorded here rather than glossed: a reader should know that the cadences were adopted by issuing the document rather than derived one by one from a risk assessment. They are amended by revising this program, the schedule page is where the change is made, and the annual review in Part 10 is the occasion that re-examines them. A frequency that turns out to be wrong is a revision, not a non-conformance.\n\n3. THE ANALYTICAL LIMB OF 2.5.1.1 i IS NOT MET, AND THIS PROGRAM DOES NOT CLAIM IT. Confirming that Good Manufacturing Practices achieve their result normally rests on measurement, and this site performs no analysis at all - no laboratory, no external laboratory, no reliance on supplier certificates of analysis. Part 2 says so and rests the confirmation on inspection and record review. The environmental monitoring program for ready-to-eat product is the deliverable that changes it, and Part 2 is revised when that is issued. This is a standing limitation of the program as issued, not an open action.\n\n4. PART 3 HAS NOTHING TO BITE ON YET, for the same kind of reason. The critical limits it governs are those a food safety plan establishes, and the site has no HACCP plan under document control and no critical control points defined. The rule stands; the activity is carried on the schedule as not yet implemented; and the two limits that ARE real today are named in Part 3 together with the statement that neither is a CCP.\n\nWHAT THIS CLOSES. 2.5.2.1 and 2.5.2.2 are in force from this date. 2.5.1.1 is met in part - limb iii by Part 4, limbs i and ii as far as a site with no analysis and no food safety plan can meet them, with both gaps stated on the document. Recording that as a full closure would be closing a Mandatory clause on evidence that does not exist.\n\nREVISED 2026-09-11 — v2, approved GJM (Senior Site Management), effective 2026-09-11. PART 3 WAS WRONG ABOUT CRITICAL CONTROL POINTS, AND PART 5 CLAIMED MORE THAN THE SITE DOES.\n\nAs issued, Part 3 said the site had no critical control points defined, and item 4 of the settled block above repeats it. That came from searching the text of every controlled document, and the search never opened attached files. The site's HACCP plan is held in the document library as an attached PDF on an unnumbered reference document, and it identifies five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. The plan has no document number and no approval, so it is not under document control, and that half of the statement stood. The other half did not.\n\nTHE FIVE POINTS ARE MONITORED BUT NOT RECORDED, confirmed on 2026-09-11. That changes two Parts. Part 3 now names the five points, and states that no critical limit for them is established by a controlled document and that there is no record to review a limit against. Part 5 gains a paragraph stating that the verification of critical control point monitoring required by 2.5.2.1 is not performed, because verification confirms a record and there is none. The two schedule activities that depend on it, CCP monitoring record review and the annual review and re-validation of critical food safety limits, stay not yet implemented, and their descriptions on the schedule are corrected to say why.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. At issue 2.5.2.1 was recorded as in force. It is in force for Good Manufacturing Practices and for the other food safety controls named in Part 1, and NOT for critical control points. Unlike the analytical limb of 2.5.1.1, this is an open action rather than a standing limitation: the points are already monitored, and what is missing is the record. It closes when the food safety plan is brought under document control with a monitoring record for each point. 2.5.1.1 remains met in part, as issued.\n\nThis revision is a correction, not the annual review of the program in Part 10, although the application records it as a revision and the schedule dates the next review from it.\n\nREVISED 2026-09-11 — v3, approved GJM (Senior Site Management), effective 2026-09-11. THE v2 CORRECTION COUNTED THE CRITICAL CONTROL POINTS WRONGLY.\n\nv2 listed five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. That list was not taken from the plan's control chart, and the plan was read in full for this revision. It defines two: CCP 1, baking, and CCP 2, vacuum sealing in pouches. Sealing and sealing leak are the biological and the physical hazard of the same step, CCP 2.\n\nTHE TWO COOLING STEPS ARE NOT CRITICAL CONTROL POINTS, although one table in the plan says they are. The plan's hazard analysis marks temperature control on the racks, and cooling to room temperature before covering, as CCP 1 and calls them kill steps. Its flow diagram marks only baking and vacuum sealing, and its control chart sets critical limits and monitoring only for those two. Cooling destroys nothing, and a step with no critical limit cannot be operated as a critical control point, so this program follows the diagram and the control chart and leaves the discrepancy to be corrected in the plan.\n\nv2 ALSO SAID THE PLAN HAS NO APPROVAL. Its cover names an approver and a version. It carries no document number, it is not under document control, and its approval page is unsigned, so the conclusion stood: no critical limit is established by a controlled document. Part 3 now says so precisely.\n\nPART 3 NOW LISTS BOTH POINTS with the hazard, critical limits and monitoring the plan states for each, and records the limits the plan has not settled: the vacuum level and seal width, given only as the equipment specification, and the validation of the bake, for which the plan recommends a lethality study rather than relying on one. Part 5 and the two schedule descriptions now say two points, not five. Nothing else changes: 2.5.2.1 remains in force for Good Manufacturing Practices and the other controls and not for critical control points, as v2 recorded, and both schedule activities stay not yet implemented.\n\nREVISED 2026-09-11 — v4, approved GJM (Senior Site Management), effective 2026-09-11. THE CRITICAL CONTROL POINTS ARE NOW RECORDED.\n\nFRM-507 CCP 1 Baking Monitoring Record and FRM-606 CCP 2 Vacuum Sealing Monitoring Record were issued on the same date. The production operator records every oven load and every sealing check on them, and each entry carries a required verification signature, so the monitoring that v2 and v3 recorded as unrecorded now has a record, and the verification 2.5.2.1 requires can be performed and authorized.\n\nPart 3 now names the two forms and states the one limit still not monitored, the internal product temperature at CCP 1, which is not probed. Part 5's paragraph on critical control points describes the verification rather than its absence, and its list of records that carry a verification signature adds FRM-507 and FRM-606. Part 6 replaces the single not-yet-implemented CCP monitoring record review with two weekly activities, one per record, first due 18 September 2026. Each is in force from this date and raises its reminder like every other active activity.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. 2.5.2.1 is now in force for critical control points as well as for Good Manufacturing Practices and the other controls, with two limitations stated on the forms: the internal product temperature at CCP 1 is not monitored, so it cannot be verified, and the CCP 2 vacuum level and seal width are verified against an equipment specification not yet confirmed for this site's machine. The annual review and re-validation of critical food safety limits stays not yet implemented, because the limits are not yet established by a controlled document or validated. 2.5.1.1 remains met in part.\n\nSOP-505 is revised on the same date so that oven temperature and bake time are recorded on FRM-507 rather than on the batch sheet, which never held them.\n\nv5 — 2026-09-16 — The annual compressed air quality analysis retired from the schedule, under D-32.\n\nPart 6 carried \"Compressed air quality analysis — Annually — NOT YET IMPLEMENTED — awaiting D-32 Compressed Air and Gases\". D-32 is answered. The site's compressed air operates pneumatic equipment, where it contacts no food and no food-contact surface, and its one other use — clearing film scraps from the flow wrapper — is now performed only with the film unloaded and the table cleared, under SOP-605 v2, and is carried in FSQM-013 as a category C alternative control. 11.5.5.2's testing obligation is scoped to air that contacts food or food-contact surfaces; with that use controlled there is no air in scope to test, and an annual analysis would be a record of nothing.\n\nThe activity is RETIRED on the schedule rather than deleted, which is how this program treats an activity that stops applying, and the line is removed from this Part. The obligation returns the moment compressed air is put into contact with product or a food-contact surface — a new machine, a blow-off drying step, or the flow wrapper being cleaned with film loaded. That is a change the annual review in Part 7 is meant to catch, and it re-opens the activity rather than waiting for the review after it.\n\nv6 — 2026-09-16 — The blackout period declaration added to the schedule, under D-05.\n\nSQF 2.1.1.8 requires senior site management to designate defined blackout periods and to submit them, with their justification, to the certification body at least one month before the sixty-day unannounced re-certification window opens. FRM-006 Blackout Period Declaration is issued with this revision as the record of that designation, and the activity joins Part 6.\n\nIT IS DATED DIFFERENTLY FROM EVERY OTHER ACTIVITY ON THIS SCHEDULE, AND DELIBERATELY SO. The rest are \"do it again a period after the last time you did it\". A blackout declaration states the period it covers, so filing it early or late says nothing about when it expires. Anchored on the filing date, a declaration signed in October for the following calendar year would come due the following October — ten months after the site was already covered — and one signed late would push its own expiry out and let the site run uncovered without the schedule noticing. It is therefore dated from the last day the declaration in force covers, and raised ninety days before the next period begins: enough notice to agree the dates, sign them and send them.\n\nNO DECLARATION HAS BEEN FILED YET, so the activity will be raised as never recorded at the next run of the reminder job. That is the intended prompt and not a fault — 2.1.1.8 is open until senior site management files one.\n\nTHE SUBMISSION LIMB REMAINS OPEN, and it is not a matter of scheduling. No certification body is engaged and no certificate is held, so there is nothing to submit to and no sixty-day window to count back from. FRM-006 Section 5 stays blank until there is one, and says so on its face.\n\nv7 — 2026-09-16 — The monthly SQF update added to the schedule, under D-06.\n\nSQF 2.1.2.2 requires the SQF Practitioner to update senior site management at least monthly on matters affecting the SQF System, and for the update and management's response to be documented. FRM-009 Monthly SQF Update Record is issued with this revision as that record, governed by FSQM-005, and the activity joins Part 6.\n\nIT WAS ASSESSED COMPLIANT AT THE GAP ASSESSMENT AND WAS NOT. The management review procedure then in draft said the monthly update was recorded in a \"Flash Report\", and no such report exists anywhere in this system. The rewritten FSQM-005 first replaced that with minutes \"retained with the management review records\", which named no form and nothing to prompt it — the same weakness one level less obvious, and caught on review before issue. FRM-009 is the answer to it: a short record, on the schedule, that prompts itself.\n\nTHE ACTIVITY WILL READ AS NEVER RECORDED until the first entry is submitted. That is the prompt working rather than a fault, and it is honest: the monthly meeting has been happening without a retained record for as long as the site has been holding it.\n\nv8 — 2026-09-21 — Calibration brought into force under D-28. FSQM-030 Calibration Program and FRM-705 Calibration Directory and Check Record are issued, so the calibration activity in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-705. It was carried as annual while no program existed; FSQM-030 sets it monthly, one session covering every device on the directory. First due 2026-10-21, a month after issue, so the 25 lb certified test weight can be bought before the first check. Nothing else in the schedule changes.\n\nv9 — 2026-09-21 — Preventive maintenance check added to Part 6 at the owner's request, so the monthly FRM-508 check is prompted by the reminder system like the other monthly activities. Carried as NOT YET IMPLEMENTED until FSQM-029 and FRM-508 are issued under D-26, when it becomes active against FRM-508. Nothing else in the schedule changes.\n\nv10 — 2026-09-21 — Preventive maintenance brought into force under D-26. FSQM-029 Preventive Maintenance Program, FRM-508 Monthly Maintenance Check and FRM-509 Maintenance and Repair Record are issued, so the preventive maintenance check in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-508. First due 2026-10-21, a month after issue. Nothing else in the schedule changes.\n\nv11 — 2026-10-01 — Internal audit brought into force under D-19. FSQM-038 Internal Audit Program and FRM-010 Internal Audit Record are issued, so the internal audit in Part 6 moves from NOT YET IMPLEMENTED to active: quarterly, evidenced by FRM-010. The SQF Practitioner keeps the audit plan on schedule; the audits themselves are carried out by the Internal Auditor appointed under FSQM-038. First raised 2026-12-01 for the Q4 2026 audit. Nothing else in the schedule changes.\n\nv12 — 2026-10-05 — Part 4 revised under D-04. FSQM-007 Change Management Program and FRM-015 Change Assessment Record are issued, so Part 4 no longer says there is no general change-assessment record: it names them, and adds FRM-202 and FRM-207 to the dedicated records. The rule itself - assess before the change takes effect - is unchanged, and so is the schedule.\n\nv13 — 2026-10-07 — Recall and crisis brought into force under D-21. FSQM-023 Product Withdrawal and Recall Program and FSQM-024 Crisis Management Plan are issued with their records, and FSQM-021 Product Identification and Traceability Program was issued on 2026-10-06. In Part 6 the traceability and mock recall test moves from NOT YET IMPLEMENTED to active: yearly, evidenced by FRM-012, first due 2026-12-31. One activity is added: the crisis management plan review and test, yearly before 1 June, Senior Site Management, evidenced by FRM-013, first due 2027-05-31. Nothing else in the schedule changes.\n\nv14 — 2026-10-07 — CCP 2 monitoring stated as it is performed. Management's decision: every pouch is looked at as it comes off the sealer, for seal defects and for air in the pouch; at boxing, once the seal is cool, every pouch is looked at again and one pouch from each lot is pull tested. The June 2026 plan's hourly pull test at the sealer is withdrawn - a warm seal can be pulled open by the test itself - and so is its gauge check on every cycle, which was not being performed. Recorded on FRM-606 v2. The record, the weekly review and the schedule are unchanged.\n\nv18 — 2026-10-29 — The food safety plan named. FSQM-016 Food Safety Plan (HACCP) - Rum Cake was issued on 2026-10-29 as a limited plan and the unnumbered June 2026 plan was archived, so Part 1 now names FSQM-016 in place of it. CCP 1 is stated as FSQM-016 states it. The limits are now under document control but not yet validated; the re-validation activity stays not yet implemented, now awaiting FSQM-016 Part 9 rather than D-14. The note about the June plan's cooling steps is replaced by a reference to FSQM-016 Parts 7 and 8. The records, the weekly reviews and the rest of the schedule are unchanged.\n\nv19 — 2026-10-29 — The environmental monitoring sampling round added to the schedule, with FSQM-015's issue: every four months, SQF Practitioner, evidenced by FRM-706, first due 2027-01-31. Nothing else in the schedule changes.\n\nv20 — 2026-10-29 — The yearly food defense and food fraud review and test added to the schedule, with the issue of FSQM-025 and FSQM-026: annually, SQF Practitioner, evidenced by FRM-014, first due 2027-01-31. Nothing else in the schedule changes.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9.\n2.5.1 Validation and Effectiveness (MANDATORY). 2.5.1.1 requires documented and implemented methods, responsibility and criteria for ensuring the effectiveness of all applicable elements of the SQF System, validating that (i) Good Manufacturing Practices achieve the required results, (ii) critical food safety limits are reviewed annually and re-validated or justified when changes occur, and (iii) changes to processes or procedures are assessed for continued control. Parts 2, 3 and 4 respectively.\n2.5.2 Verification Activities (MANDATORY). 2.5.2.1 requires documented and implemented methods, responsibility and criteria for verifying the monitoring of GMPs, critical control points and other food safety controls, and requires that the personnel responsible for verifying monitoring authorize each verified record — Part 5. 2.5.2.2 requires a verification schedule stating the activities, their frequency and the person responsible, and that records of verification are maintained — Part 6 is the schedule, and Part 9 states where the records are held.\n2.5.3 Corrective and Preventative Action, and FSQM-009 — where a failed verification goes. This program routes to it and does not restate it.\n2.5.4.3 Regular inspections of site and equipment, and FSQM-022 — the monthly Module 11 inspection this program schedules and relies on, but does not define.\n2.1.2 Management Review — the annual review this program schedules on FRM-001."}$jx$::jsonb,
       revision = 'v20', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-017' and status = 'active' and revision = 'v19';

insert into public.verification_schedule
  (activity_key, activity, description, frequency_unit, frequency_count, responsible_position, evidence_kind,
   evidence_document_number, owning_program, sqf_reference, lead_days, grace_days, first_due_on, status, sort_order)
values
  ('food_defense_fraud_review', 'Food defense and food fraud review and test',
   'The yearly review of the food defense threat assessment and plan (FSQM-025), with its unannounced walk-in test, and the yearly review and verification of the food fraud vulnerability assessment and mitigation plan (FSQM-026). Both recorded on FRM-014, with the name of the responsible senior manager.',
   'year', 1, 'SQF Practitioner', 'form_entry', 'FRM-014', 'FSQM-025', '2.7.1.4, 2.7.2.4', 30, 30, date '2027-01-31', 'active', 270);

do $verify$
begin
  if (select count(*) from public.sop_documents where sop_number in ('FSQM-025','FSQM-026','FRM-014','REP-905') and status = 'active' and approved_by = 'GJM') <> 4 then
    raise exception 'not all four documents were issued.';
  end if;
  if (select (content->'procedure')::text like '%kept locked away from food%' from public.sop_documents where sop_number = 'FSQM-025') then
    raise exception 'FSQM-025 still says chemicals are locked away.';
  end if;
  if (select count(*) from public.sop_documents where sop_number in ('FSQM-025','FSQM-026') and (content->'procedure')::text like '%Stated limitations at issue%') <> 2 then
    raise exception 'a limitations Part is missing.';
  end if;
  if (select revision from public.sop_documents where sop_number = 'FSQM-017') <> 'v20' then raise exception 'FSQM-017 not revised.'; end if;
  if not exists (select 1 from public.verification_schedule where activity_key = 'food_defense_fraud_review' and status = 'active') then raise exception 'schedule row missing.'; end if;
end $verify$;

commit;
